import {UNITS,MODES,taskLevel,modeTotals,measurement,unitInfo,quantitySummary,setting,leaves,ancestry,descendants,shiftDate,weekStart} from './model.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const numberText=n=>new Intl.NumberFormat('ja-JP',{maximumFractionDigits:3}).format(n);
export function quantitySettingsFields(s,id,required=true){const m=measurement(s,id);return `<div class="quantity-config"><h3>タスクの量</h3><div class="form-columns"><label>単位<select name="quantity-unit" data-quantity-unit>${Object.entries(UNITS).map(([k,u])=>`<option value="${k}" ${m.unit===k?'selected':''}>${u.label}</option>`).join('')}<option value="custom" ${m.unit==='custom'?'selected':''}>自由に入力</option></select></label><label>1回の固定量<input type="number" inputmode="decimal" name="daily-amount" min="0.001" max="1000000" step="any" ${required?'required':''} value="${m.dailyAmount??''}" placeholder="例：10"></label></div><label data-custom-unit ${m.unit==='custom'?'':'hidden'}>単位の名前<input name="custom-unit" maxlength="12" value="${esc(m.customUnit||'')}" placeholder="例：曲、km、セット"></label><p class="footnote">どのモードでも、このタスクの量は同じです。</p><details class="weekly-target-details" ${m.weeklyTarget!=null?'open':''}><summary>週の目標量（任意）</summary><label>週の目標量<input type="number" inputmode="decimal" name="weekly-target" min="0.001" max="1000000" step="any" value="${m.weeklyTarget??''}" placeholder="設定しなくても使えます"></label></details></div>`}
export function taskLevelFields(a,name='task-level'){return `<fieldset class="fixed-mode-settings"><legend>このタスクを始めるモード</legend>${['rest','busy','full'].map(m=>`<label class="checkbox-label"><input type="radio" name="${esc(name)}" value="${m}" ${taskLevel(a)===m?'checked':''}>${MODES[m].icon} ${MODES[m].label}</label>`).join('')}<p class="footnote">休む日のタスクは毎日、忙しい日のタスクは忙しい日と余裕がある日、余裕がある日のタスクは余裕がある日に含まれます。</p></fieldset>`}
export function presetPanel(s,id){const n=s.nodes.find(n=>n.id===id),a=setting(s,id);if(!n)return '';return `<form id="preset-form" data-id="${esc(id)}"><div class="dialog-title"><div><div class="eyebrow">${esc(ancestry(s,id).slice(1,-1).join(' / ')||'自分の宇宙')}</div><h2>${esc(n.name)}</h2></div><button type="button" class="round-button" data-do="close" aria-label="閉じる">×</button></div>${quantitySettingsFields(s,id)}${taskLevelFields(a)}${a.status!=='active'?`<p class="footnote">このタスクは${a.status==='paused'?'一時停止':'完了'}中です。有効に戻すには詳細設定を開いてください。</p>`:''}<div class="dialog-actions"><button type="button" class="text-button" data-edit="${esc(id)}">名前・親目標などを編集</button><button class="primary" type="submit">タスクを保存</button></div><button type="button" class="text-button record-adjust-button" data-record-leaf="${esc(id)}">今日の記録を調整</button></form>`}
export function modePickerContent(s,key){const current=s.records[key]?.mode;return `<div class="dialog-title"><div><div class="eyebrow">${Number(key.slice(5,7))}月${Number(key.slice(8))}日</div><h2>今日は、どのペース？</h2></div><button class="round-button" data-do="close" aria-label="閉じる">×</button></div><p class="mode-picker-note">行動に保存した固定量を、そのまま反映します。</p><div class="quick-mode-options">${['full','busy','rest'].map(k=>{const m=MODES[k],summary=modeTotals(s,k);return `<button data-mode="${k}" data-date="${key}" class="quick-mode ${k} ${current===k?'chosen':''}"><span class="quick-mode-icon">${m.icon}</span><div><strong>${m.label}</strong><small>${summary.count?summary.groups.map(g=>`${numberText(g.total)}${esc(g.unit)}`).join(' ・ '):'固定量を設定したタスクはありません'}</small></div><i>${current===k?'✓':'→'}</i></button>`}).join('')}</div>${Object.values(s.logs[key]||{}).some(l=>l.quantity&&l.source!=='mode')?'<p class="footnote">この日だけ修正した量は、そのまま残ります。</p>':''}<div class="mode-picker-footer"><button class="text-button" data-configure-leaves>行動の量を設定する</button><button class="text-button quiet" data-do="close">あとで</button></div>`}
export function recordPanel(s,id,date,today){const n=s.nodes.find(n=>n.id===id);if(!n)return '';const old=s.logs[date]?.[id],m=old?.quantity?.measurement||measurement(s,id),u=unitInfo(m),week=weekStart(date),summary=quantitySummary(s,week,shiftDate(week,6),id,week===weekStart(today)),group=summary.groups.find(g=>g.dimension===u.dimension),amount=old?.quantity?.amount??m.dailyAmount??'',active=setting(s,id);const increments=u.dimension==='time'?(u.label==='分'?[10,30,60]:[.25,.5,1]):[1,5,10];return `<form id="quantity-form" data-id="${esc(id)}"><div class="dialog-title"><div><div class="eyebrow">${esc(ancestry(s,id).slice(1,-1).join(' / ')||'自分の宇宙')}</div><h2>${esc(n.name)}</h2></div><button type="button" class="round-button" data-do="close" aria-label="閉じる">×</button></div><label>記録する日<input type="date" name="record-date" value="${date}" max="${today}" required></label><label class="quantity-input-label">この日の合計<div class="quantity-input"><input name="amount" type="number" inputmode="decimal" min="0.001" max="1000000" step="any" value="${amount}" placeholder="0" required autofocus><span>${esc(u.label)}</span></div></label><div class="quantity-increments">${increments.map(v=>`<button type="button" data-add-quantity="${v}">＋${numberText(v)}${esc(u.label)}</button>`).join('')}</div><div class="record-week-summary"><span>この週の合計</span><strong>${numberText(group?.total||0)}<small>${esc(group?.unit||(u.dimension==='time'?'時間':u.label))}</small></strong></div>${old&&!old.quantity?'<p class="footnote">この日には以前のチェック記録があります。量はまだ記録されていません。</p>':''}${old?.source==='mode'?'<p class="footnote">モードから反映した量です。この日だけ修正できます。</p>':''}${old?.quantity?'<p class="footnote">保存すると、この日の合計を更新します。過去の記録の単位を使用しています。</p>':'<p class="footnote">1日に何回か取り組んだ場合は、合計量を入力してください。</p>'}${active.type==='once'?'<p class="footnote">記録すると、この行動は完了になります。</p>':''}<div class="dialog-actions"><button type="button" class="text-button" data-open-preset="${esc(id)}">タスクの量を設定</button><button type="submit" class="primary">量を記録する</button></div>${old?`<button type="button" class="text-button danger remove-quantity" data-remove-quantity="${esc(id)}" data-log-date="${date}">この日の記録を削除</button>`:''}</form>`}
function readableQuantity(amount,dimension,unit){return dimension==='time'&&amount>0&&amount<1?{amount:Math.round(amount*60000)/1000,unit:'分'}:{amount,unit}}
export function weeklyPanel(s,{week,scope,dimension,today}){
 const end=shiftDate(week,6),current=weekStart(today),summary=quantitySummary(s,week,end,scope,week===current),groups=summary.groups.filter(g=>g.total>0),group=groups.find(g=>g.dimension===dimension)||groups[0],dates=Array.from({length:7},(_,i)=>shiftDate(week,i)),max=Math.max(1,...dates.map(d=>group?.byDate[d]||0)),activeLeaves=new Set(leaves(s).map(n=>n.id));
 return `<section class="quantity-overview" aria-label="今週の記録"><header class="quantity-week-heading"><h1>${week===current?'今週の記録':'週の記録'}</h1><div class="week-navigation"><button class="round-button" data-quantity-week="-1" aria-label="前の週">‹</button><span>${Number(week.slice(5,7))}/${Number(week.slice(8))} – ${Number(end.slice(5,7))}/${Number(end.slice(8))}</span><button class="round-button" data-quantity-week="1" aria-label="次の週" ${week>=current?'disabled':''}>›</button></div></header>
 ${groups.length?`<div class="quantity-totals">${groups.map(g=>{const shown=readableQuantity(g.total,g.dimension,g.unit);return `<button class="quantity-total ${group===g?'chosen':''}" data-quantity-dimension="${esc(g.dimension)}" aria-pressed="${group===g}" aria-label="${esc(g.unit)}の日別グラフを選ぶ"><strong>${numberText(shown.amount)}</strong><span>${esc(shown.unit)}</span></button>`}).join('')}</div>`:`<div class="weekly-no-record"><p>この週は、まだ記録がありません。</p><button class="text-button" data-do="today-mode">今日のモードを選ぶ →</button></div>`}
 <div class="quantity-section-title"><h2>タスク別</h2><button class="text-button" data-reset-week ${week===current?'hidden':''}>今週へ戻る</button></div><div class="quantity-action-list">${summary.rows.map(row=>{const shown=readableQuantity(row.amount,row.dimension,row.unit),pct=row.target?Math.round(row.amount/row.target*100):null,editable=!row.deleted&&activeLeaves.has(row.id);return `<div class="quantity-action"><div class="quantity-action-top"><div><strong>${esc(row.name)}</strong>${row.deleted?'<small>過去のタスク</small>':''}</div><div><b>${numberText(shown.amount)}</b><span>${esc(shown.unit)}</span>${editable?`<button class="quantity-row-edit" data-record-leaf="${esc(row.id)}" aria-label="${esc(row.name)}の記録を修正">›</button>`:''}</div></div>${pct!=null?`<div class="quantity-target-bar"><i style="width:${Math.min(100,pct)}%"></i></div><p class="quantity-target-caption">目標 ${numberText(row.target)}${esc(row.unit)}</p>`:''}</div>`}).join('')||'<p class="quantity-list-empty">行動に固定量を設定すると、ここに表示されます。</p><button class="text-button" data-view="tree">自分の宇宙へ →</button>'}</div>
 ${group?`<details class="daily-chart-details"><summary>日ごとの内訳 <span>${esc(group.unit)}</span></summary><div class="quantity-chart" aria-label="${esc(group.unit)}の1週間の記録">${dates.map((d,i)=>{const v=group.byDate[d]||0;return `<button class="quantity-day ${d===today?'today':''}" data-quantity-day="${d}" aria-label="${d.slice(5).replace('-','月')}日 ${numberText(v)}${esc(group.unit)}" ${d>today?'disabled':''}><span class="bar-value">${v?numberText(v):''}</span><div class="bar-track"><i style="height:${v?Math.max(3,v/max*100):2}%;opacity:${v?1:.25}"></i></div><span>${['月','火','水','木','金','土','日'][i]}</span></button>`}).join('')}</div></details>`:''}
 ${summary.entries.some(e=>e.source==='mode')?'<p class="quantity-source-note">モードから反映した固定量を含みます。</p>':''}${summary.unknown?`<p class="quantity-source-note">量の未記録 ${summary.unknown}件</p>`:''}</section>`
}
export function scopeOptions(s,selected){const root=s.nodes.find(n=>n.parentId===null),out=[];function walk(n,depth){out.push(`<option value="${esc(n.id)}" ${selected===n.id?'selected':''}>${'　'.repeat(depth)}${esc(n.name)}</option>`);s.nodes.filter(c=>c.parentId===n.id).forEach(c=>walk(c,depth+1))}if(root)walk(root,0);return `<option value="all" ${selected==='all'?'selected':''}>宇宙全体</option>`+out.join('')}
